class Solution {
    public int[] searchRange(int[] nums, int target) {
        int[]res = new int[]{-1,-1};
        int res0 = findMid(nums,target);
        int res1 = findMid(nums,target+1);
        if(res0<nums.length && nums[res0] ==target){
            res[0] =res0;
            res[1] = res1-1;
            return res;
        }
        return res;
    }
    public int findMid(int[]nums,int target){
        int L = 0;
        int R = nums.length;
        while(L<R){
            int mid = L + (R-L)/2;
            if(nums[mid]>=target){
                R = mid;
            }else{
                L = mid+1;
            }
        }
        return L;
    }
}
